  b$e = `Touch`,
  x$e = `This command will be sent when the pad is touched.`,
  S$e = `Style of Input - Joystick Camera`,
  C$e = `This input will operate as a joystick optimized for controlling a first or third person camera.  Joystick will only work with XInput compatible gamepad games.`,
  w$e = `Output Joystick`,
