  cpt = `Snap Back Disabled`,
  lpt = `This will leave the mouse postition as-is on the release of the trackpad or end of the mode shift.`,
  upt = `Horizontal Scale`,
  dpt = `Scale the horizontal region.  You can use this to change the on-screen region from a circle to an ellipse or a line.`,
  fpt = `Rotate Output`,
  ppt = `Rotates the output to the joystick, such that pushing the physical stick "North" results in an output of "East", when set to 90°`,
  mpt = `Vertical Scale`,
  hpt = `Scale the vertical region.  You can use this to change the on-screen region from a circle to an ellipse or a line.`,
